<?php
declare(strict_types=1);require_once dirname(__DIR__,2).'/bootstrap.php';require_post();$sender=require_auth();$p=db();try{$d=request_json();$uid=(int)$sender['id'];$key=v17_key($d);$kind=$giftTargetKind??'stream';$id=(int)($d[$kind==='stream'?'streamId':($kind==='clip'?'clipId':'recordingId')]??0);$giftId=(int)($d['giftId']??0);$audio=(string)($d['audioUrl']??'');$audioName=text_substr((string)($d['audioName']??''),0,120);if($id<1||$giftId<1||($audio!==''&&!preg_match('#^\.\./uploads/gift-audio/[a-zA-Z0-9_.-]+$#D',$audio)))json_response(['message'=>'Geçersiz hediye.'],400);$cached=v17_begin($uid,$key,'gift.'.$kind,[$id,$giftId,$audio,$audioName]);if($cached){$cached['walletBalance']=(int)fetch_user_by_id($uid)['wallet_balance'];json_response($cached);}
if($kind==='stream'){$r=v17_query('SELECT * FROM streams WHERE id=? AND is_live=1 FOR UPDATE',[$id])->fetch();if(!$r)throw new RuntimeException('Yayın aktif değil.');$owner=(int)$r['user_id'];$sid=$id;if(!v17_can_view_profile($owner,$sender))throw new RuntimeException('Bu hesap gizli.');}else{$r=v17_content($kind,$id,$sender);$owner=(int)$r[$kind==='clip'?'streamer_user_id':'user_id'];$sid=$r['stream_id']?(int)$r['stream_id']:null;}if($owner===$uid)throw new RuntimeException('Kendi içeriğine hediye gönderemezsin.');$g=v17_query('SELECT * FROM gift_catalog WHERE id=?',[$giftId])->fetch();if(!$g)throw new RuntimeException('Hediye bulunamadı.');$price=(int)$g['price'];$clipper=$kind==='clip'?(int)$r['created_by_user_id']:$owner;$share=$clipper!==$owner?(int)floor($price*.1):0;
v17_query('SELECT id FROM users WHERE id IN (?,?,?) ORDER BY id FOR UPDATE',[$uid,$owner,$clipper])->fetchAll();debit_wallet($uid,$price,'gift_sent',$g['name'].' hediyesi',$owner);credit_creator_earnings($owner,$price-$share,$g['name'].' hediyesi',$uid);if($share)credit_creator_earnings($clipper,$share,'Klip üretici payı',$uid);v17_query('UPDATE users SET total_gifts_received=total_gifts_received+? WHERE id=?',[$price,$owner]);
if($kind==='clip'){v17_query('INSERT INTO clip_gifts(clip_id,sender_user_id,streamer_user_id,clipper_user_id,amount,streamer_share,clipper_share) VALUES (?,?,?,?,?,?,?)',[$id,$uid,$owner,$clipper,$price,$price-$share,$share]);$eid=(int)$p->lastInsertId();}else{v17_query('INSERT INTO gift_events(stream_id,sender_user_id,recipient_user_id,gift_id,quantity,unit_price,total_price,audio_url,audio_name,recording_id) VALUES (?,?,?,?,1,?,?,?,?,?)',[$sid,$uid,$owner,$giftId,$price,$price,$audio?:null,$audioName?:null,$kind==='recording'?$id:null]);$eid=(int)$p->lastInsertId();v17_query("INSERT INTO gift_settlements(gift_event_id,recipient_user_id,amount,destination_mode,status) VALUES (?,?,?,'creator_earnings','available')",[$eid,$owner,$price]);if($kind==='stream'){v17_query('UPDATE streams SET gift_total=gift_total+? WHERE id=?',[$price,$sid]);v17_query("UPDATE community_goals SET current_amount=LEAST(target_amount,current_amount+?),status=IF(current_amount>=target_amount,'completed',status) WHERE stream_id=? AND status='active'",[$price,$sid]);}}
$event=['id'=>$eid,'eventId'=>$eid,'kind'=>$kind,'streamId'=>$sid,'recordingId'=>$kind==='recording'?$id:null,'giftId'=>$giftId,'giftName'=>$g['name'],'giftIcon'=>$g['icon'],'quantity'=>1,'unitPrice'=>$price,'totalPrice'=>$price,'senderUserId'=>$uid,'recipientUserId'=>$owner,'senderName'=>$sender['display_name'],'senderAvatar'=>$sender['avatar_url']??null,'audioUrl'=>$audio?:null,'audioName'=>$audioName?:null];$response=['message'=>'Hediye gönderildi.','walletBalance'=>(int)fetch_user_by_id($uid)['wallet_balance'],'event'=>$event,'settlementMode'=>'creator_earnings'];create_notification($owner,$uid,'gift','Yeni hediye',$sender['display_name'].' sana 1 × '.$g['name'].' gönderdi.','./profile.php#gifts');v14_publish($kind==='stream'?'gift.sent':'content.gift',$event,$kind==='stream'?null:$owner,$kind==='stream'?$sid:null,'stream.'.$sid);v17_finish($uid,$key,$response);json_response($response);
}catch(Throwable $e){if($p->inTransaction())$p->rollBack();error_log('[BUFF gift] '.$e->getMessage());$known=in_array($e->getMessage(),['Yetersiz bakiye.','Yayın aktif değil.','Bu hesap gizli.','Kendi içeriğine hediye gönderemezsin.','Hediye bulunamadı.']);json_response(['message'=>$known?$e->getMessage():'Hediye tamamlanamadı. Aynı işlem tekrar denenebilir.'],$known?400:500);}
